<script setup lang="ts">
import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import{NButton,NInput,NModal,NFormItem,NEmpty,useMessage}from'naive-ui';import{api}from'../api';
const contests=ref<any[]>([]),title=ref(''),show=ref(false),router=useRouter(),message=useMessage();
onMounted(async()=>{try{contests.value=await api('/contests');}catch(e){message.error((e as Error).message);}});
async function create(){try{const c=await api('/contests',{method:'POST',body:JSON.stringify({expectedVersion:0,data:{title:title.value,author:'',stage:'',dateHeader:'',dateCover:'',language:'zh-CN',templates:{STATEMENT:null,EDITORIAL_DOCUMENT:null,EDITORIAL_BEAMER:null},items:[]}})});await router.push(`/contests/${c.id}`);}catch(e){message.error((e as Error).message);}}
</script>
<template><div class="page-heading"><div><h1>比赛</h1><p>编排已冻结题目修订，组装题册与两种题解</p></div><NButton type="primary" @click="show=true">创建比赛</NButton></div><div class="panel"><table class="data-table" v-if="contests.length"><thead><tr><th>比赛名称</th><th>编排版本</th><th>最近更新</th><th></th></tr></thead><tbody><tr v-for="c in contests" :key="c.id"><td><RouterLink :to="`/contests/${c.id}`">{{c.title}}</RouterLink><small>{{c.id}}</small></td><td>v{{c.version}}</td><td>{{new Date(c.updatedAt).toLocaleString('zh-CN')}}</td><td><NButton @click="router.push(`/contests/${c.id}`)">打开比赛</NButton></td></tr></tbody></table><NEmpty v-else class="empty" description="创建比赛并选择已冻结的题目"/></div><NModal v-model:show="show" title="创建私有比赛" preset="card" style="width:480px"><NFormItem label="比赛名称"><NInput v-model:value="title" :maxlength="160"/></NFormItem><NButton type="primary" :disabled="!title.trim()" @click="create">创建</NButton></NModal></template>
